import std.collection.HashMap
import std.time.DateTime

class AccessGatewayFilter {
    /*
    This class is a filter used for accessing gateway filtering, primarily for authentication and access log recording.
    */

    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        let request_uri = request.get("path").as(String)
        let method = request.get("method").as(String)

        if (this.is_start_with(request_uri)) {
            return true
        }

        match this.get_jwt_user(request) {
            Option.Some(token) => {
                let user = token.get("user").as(HashMap<String, Any>)
                if (user.get("level").as(Int) > 2) {
                    this.set_current_user_info_and_log(user)
                    return true
                }
                return false
            },
            Option.None => {
                return false
            }
        }
    }

    public func is_start_with(request_uri: String): Bool {
        let start_with = ["/api", "/login"]
        for (s in start_with) {
            if (request_uri.startsWith(s)) {
                return true
            }
        }
        return false
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers = request.get("headers").as(HashMap<String, Any>)
        let authorization = headers.get("Authorization").as(HashMap<String, Any>)
        let user = authorization.get("user").as(HashMap<String, Any>)
        let jwt = authorization.get("jwt").as(String)
        let name = user.get("name").as(String)

        if (jwt.startsWith(name)) {
            let jwt_str_date = jwt.substring(name.length())
            match DateTime.parse(jwt_str_date, "yyyy-MM-dd") {
                Option.Some(jwt_date) => {
                    let diff = DateTime.now().difference(jwt_date)
                    if (diff.days() >= 3) {
                        return Option.None
                    }
                    return Option.Some(authorization)
                },
                Option.None => {
                    return Option.None
                }
            }
        }
        return Option.None
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        let name = user.get("name").as(String)
        let address = user.get("address").as(String)
        let now = DateTime.now().format("yyyy-MM-dd HH:mm:ss")
        // Simulate logging
        println(name + address + now)
    }
}

import std.math.*

class AreaCalculator {
    /*
    This is a class for calculating the area of different shapes, including circle, sphere, cylinder, sector and annulus.
    */

    let radius: Float64

    public init(radius: Float64) {
        /*
        Initialize the radius for shapes.
        :param radius: Float64
        */
        this.radius = radius
    }

    public func calculate_circle_area(): Float64 {
        /*
        calculate the area of circle based on this.radius
        :return: area of circle, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_circle_area()
        12.566370614359172
        */
        return pi * this.radius ** 2
    }

    public func calculate_sphere_area(): Float64 {
        /*
        calculate the area of sphere based on this.radius
        :return: area of sphere, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_sphere_area()
        50.26548245743669
        */
        return 4 * pi * this.radius ** 2
    }

    public func calculate_cylinder_area(height: Float64): Float64 {
        /*
        calculate the area of cylinder based on this.radius and height
        :param height: height of cylinder, Float64
        :return: area of cylinder, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_cylinder_area(3.0)
        62.83185307179586
        */
        return 2 * pi * this.radius * (this.radius + height)
    }

    public func calculate_sector_area(angle: Float64): Float64 {
        /*
        calculate the area of sector based on this.radius and angle
        :param angle: angle of sector, Float64
        :return: area of sector, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_sector_area(3.1415926)
        6.283185307179586
        */
        return this.radius ** 2 * angle / 2
    }

    public func calculate_annulus_area(inner_radius: Float64, outer_radius: Float64): Float64 {
        /*
        calculate the area of annulus based on inner_radius and out_radius
        :param inner_radius: inner radius of sector, Float64
        :param outer_radius: outer radius of sector, Float64
        :return: area of annulus, Float64
        >>> areaCalculator = AreaCalculator(2.0)
        >>> areaCalculator.calculate_annulus_area(2.0, 3.0)
        15.707963267948966
        */
        return pi * (outer_radius ** 2 - inner_radius ** 2)
    }
}

import std.collection.*
import std.reflect.*
import std.convert.*

class ArgumentParser {
    /*
    This is a class for parsing command line arguments to a dictionary.
    */

    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        /*
        Initialize the fields.
        this.arguments is a dict that stores the args in a command line
        this.required is a set that stores the required arguments
        this.types is a dict that stores type of every arguments.
        >>> parser.arguments
        {'key1': 'value1', 'option1': true}
        >>> parser.required
        {'arg1'}
        >>> parser.types
        {'arg1': 'type1'}
        */
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        /*
        Parses the given command line argument string and invoke convert_type to stores the parsed result in specific type in the arguments dictionary.
        Checks for missing required arguments, if any, and returns false with the missing argument names, otherwise returns false.
        :param command_string: String, command line argument string, formatted like "python script.py --arg1=value1 -arg2 value2 --option1 -option2"
        :return (true, None) if parsing is successful, (false, missing_args) if parsing fails,
            where missing_args is a set of the missing argument names which are String.
        >>> parser.parse_arguments("python script.py --arg1=value1 -arg2 value2 --option1 -option2")
        (true, None)
        >>> parser.arguments
        {'arg1': 'value1', 'arg2': 'value2', 'option1': true, 'option2': true}
        */
        let args = command_string.split(' ')
        let args_list = args.drop(1)
        let args_size = args_list.size()
        let i = 0

        while i < args_size {
            let arg = args_list[i]
            if arg.starts_with("--") {
                let key_value = arg.substring(2).split('=')
                if key_value.size() == 2 {
                    let key = key_value[0]
                    let value = key_value[1]
                    arguments.put(key, convert_type(key, value))
                } else {
                    let key = key_value[0]
                    arguments.put(key, true)
                }
            } else if arg.starts_with("-") {
                let key = arg.substring(1)
                if i + 1 < args_size && !args_list[i+1].starts_with("-") {
                    let value = args_list[i+1]
                    arguments.put(key, convert_type(key, value))
                    i = i + 1
                } else {
                    arguments.put(key, true)
                }
            }
            i = i + 1
        }

        let arg_keys = arguments.keys().to_hash_set()
        let missing_args = required.difference(arg_keys)
        if !missing_args.is_empty() {
            return (false, Option.some(missing_args))
        }

        return (true, Option.none())
    }

    public func get_argument(key: String): Any {
        /*
        Retrieves the value of the specified argument from the arguments dictionary and returns it.
        :param key: String, argument name
        :return: The value of the argument, or None if the argument does not exist.
        >>> parser.arguments
        {'arg1': 'value1', 'arg2': 'value2', 'option1': true, 'option2': true}
        >>> parser.get_argument('arg2')
        'value2'
        */
        return arguments.get(key).unwrap_or(())
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        /*
        Adds an argument to this.types and this.required.
        Check if it is a required argument and store the argument type.
        If the argument is set as required, it will be added to the required set.
        The argument type and name are stored in the types dictionary as key-value pairs.
        :param arg: String, argument name
        :param required: Bool, whether the argument is required, default is false
        :param arg_type: TypeInfo, Argument type, default is String
        >>> parser.add_argument('arg1', true, TypeInfo.of<Int64>())
        >>> parser.required
        {'arg1'}
        >>> parser.types
        {'arg1': Int64}
        */
        if required {
            required.add(arg)
        }
        types.put(arg, arg_type)
    }

    public func convert_type(arg: String, value: String): Any {
        /*
        Try to convert the type of input value by searching in this.types.
        :param value: String, the input value in command line
        :return: return corresponding value in this.types if convert successfully, or the input value oherwise
        >>> parser.types
        {'arg1': Int64}
        >>> parser._convert_type('arg1', '21')
        21
        */
        let type_info = types.get(arg)
        if type_info.is_none() {
            return value
        }
        let t = type_info.unwrap()
        if t.equals(TypeInfo.of<Int64>()) {
            let parsed = value.to_int64()
            if parsed.is_ok() {
                return parsed.unwrap()
            }
        } else if t.equals(TypeInfo.of<Int32>()) {
            let parsed = value.to_int32()
            if parsed.is_ok() {
                return parsed.unwrap()
            }
        } else if t.equals(TypeInfo.of<Float64>()) {
            let parsed = value.to_float64()
            if parsed.is_ok() {
                return parsed.unwrap()
            }
        } else if t.equals(TypeInfo.of<Float32>()) {
            let parsed = value.to_float32()
            if parsed.is_ok() {
                return parsed.unwrap()
            }
        } else if t.equals(TypeInfo.of<Bool>()) {
            if value == "true" {
                return true
            } else if value == "false" {
                return false
            }
        }
        return value
    }
}

import std.collection.ArrayList

class ArrangementCalculator {
    let datas: ArrayList<Int64>

    public init(datas: ArrayList<Int64>) {
        this.datas = datas
    }

    public static func count(n: Int64, m: Option<Int64>): Int64 {
        let m_value = m.getOrElse(n)
        if (m_value == n) {
            return factorial(n)
        } else {
            return factorial(n) / factorial(n - m_value)
        }
    }

    public static func count_all(n: Int64): Int64 {
        var total: Int64 = 0
        for (i in 1..(n + 1)) {
            total += count(n: n, m: Some(i))
        }
        return total
    }

    public func select(m: Option<Int64>): ArrayList<ArrayList<Int64>> {
        let m_value = m.getOrElse(this.datas.size)
        let result = ArrayList<ArrayList<Int64>>()
        select_permutations(ArrayList<Int64>(), this.datas, m_value, result)
        return result
    }

    public func select_all(): ArrayList<ArrayList<Int64>> {
        let result = ArrayList<ArrayList<Int64>>()
        for (i in 1..(this.datas.size + 1)) {
            result.extend(this.select(m: Some(i)))
        }
        return result
    }

    public static func factorial(n: Int64): Int64 {
        var result: Int64 = 1
        for (i in 2..(n + 1)) {
            result *= i
        }
        return result
    }

    private func select_permutations(prefix: ArrayList<Int64>, remaining: ArrayList<Int64>, m: Int64, result: ArrayList<ArrayList<Int64>>): Unit {
        if (prefix.size == m) {
            result.add(ArrayList<Int64>(prefix))
            return
        }
        for (i in 0..remaining.size) {
            let new_prefix = ArrayList<Int64>(prefix)
            new_prefix.add(remaining[i])
            let new_remaining = ArrayList<Int64>(remaining)
            new_remaining.remove(at: i)
            select_permutations(new_prefix, new_remaining, m, result)
        }
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class Student <: Equatable<Student>{

    let name: String
    let grade: Int64
    let major: String
    let cources: HashMap<String, Int64>

    public init(name: String, grade: Int64, major: String) {
        this.name = name
        this.grade = grade
        this.major = major
        this.cources = HashMap<String, Int64>()
    }

    public override operator func != (that: Student): Bool {
        return !(this == that)
    }

    public override operator func == (that: Student): Bool {
        if (this.name != that.name) {
            return false
        }
        if (this.grade != that.grade) {
            return false
        }
        if (this.major != that.major) {
            return false
        }
        if (this.cources.size() != that.cources.size()) {
            return false
        }
        for ((k, v) in this.cources) {
            if (!that.cources.contains(k) || that.cources[k] != v) {
                return false
            }
        }
        return true
    }
}

class AssessmentSystem {

    let students: HashMap<String, Student>

    public init() {
        this.students = HashMap<String, Student>()
    }

    public func add_student(name: String, grade: Int64, major: String): Unit {
        let student = Student(name: name, grade: grade, major: major)
        this.students.put(name, student)
    }

    public func add_course_score(name: String, course: String, score: Int64): Unit {
        if (this.students.contains(name)) {
            let student = this.students[name]
            student.cources.put(course, score)
        }
    }

    public func get_gpa(name: String): Option<Float64> {
        if (!this.students.contains(name)) {
            return None
        }
        let student = this.students[name]
        let courses = student.cources
        if (courses.isEmpty()) {
            return None
        }
        var total: Int64 = 0
        for ((_, score) in courses) {
            total += score
        }
        return Some(Float64(total) / Float64(courses.size()))
    }

    public func get_all_students_with_fail_course(): ArrayList<String> {
        let result = ArrayList<String>()
        for ((name, student) in this.students) {
            for ((_, score) in student.cources) {
                if (score < 60) {
                    result.add(name)
                    break
                }
            }
        }
        return result
    }

    public func get_course_average(course: String): Option<Float64> {
        var total: Int64 = 0
        var count: Int64 = 0
        for ((_, student) in this.students) {
            if (student.cources.contains(course)) {
                let score = student.cources[course]
                if (score >= 0) {
                    total += score
                    count += 1
                }
            }
        }
        if (count > 0) {
            return Some(Float64(total) / Float64(count))
        } else {
            return None
        }
    }

    public func get_top_student(): Option<String> {
        var top_student: String? = None
        var top_gpa: Float64 = 0.0
        for ((name, _) in this.students) {
            let gpa_opt = this.get_gpa(name)
            match (gpa_opt) {
                Some(gpa) => {
                    if (gpa > top_gpa) {
                        top_gpa = gpa
                        top_student = Some(name)
                    }
                }
                None => {}
            }
        }
        return top_student
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.unicode.UnicodeStringExtension

class AutomaticGuitarSimulator {

    /*
    This class is an automatic guitar simulator that can interpret and play based on the input guitar sheet music.
    */

    let play_text: String

    public init(text: String) {
        /*
        Initialize the score to be played
        :param text:String, score to be played
        */
        this.play_text = text
    }

    public func interpret(display!: Bool = false): ArrayList<HashMap<String, String>> {
        /*
        Interpret the music score to be played
        :param display:Bool, representing whether to print the interpreted score
        :return: list of HashMap, The HashMap includes two fields, Chord and Tune, which are letters and numbers, respectively. If the input is empty or contains only whitespace, an empty list is returned.
        >>> context = AutomaticGuitarSimulator("C53231323 Em43231323 F43231323 G63231323")
        >>> play_list = context.interpret(display: false)
        [{'Chord': 'C', 'Tune': '53231323'}, {'Chord': 'Em', 'Tune': '43231323'}, {'Chord': 'F', 'Tune': '43231323'}, {'Chord': 'G', 'Tune': '63231323'}]

        */
        if this.play_text.trim().isEmpty() {
            return ArrayList<HashMap<String, String>>()
        } else {
            let play_list = ArrayList<HashMap<String, String>>()
            let play_segs = this.play_text.split(" ")
            for play_seg in play_segs {
                var pos = 0
                for ele in play_seg {
                    if ele.isLetter() {
                        pos += 1
                        continue
                    }
                    break
                }
                let play_chord = play_seg.substring(0, pos)
                let play_value = play_seg.substring(pos)
                let map = HashMap<String, String>()
                map.put("Chord", play_chord)
                map.put("Tune", play_value)
                play_list.add(map)
                if display {
                    this.display(key: play_chord, value: play_value)
                }
            }
            return play_list
        }
    }

    public func display(key: String, value: String): String {
        /*
        Print out chord and play tune with following format: Normal Guitar Playing -- Chord: %s, Play Tune: %s
        :param key:String, chord
        :param value:String, play tune
        :return: String
        >>> context = AutomaticGuitarSimulator("C53231323 Em43231323 F43231323 G63231323")
        >>> context.display("C", "53231323")
        Normal Guitar Playing -- Chord: C, Play Tune: 53231323

        */
        return "Normal Guitar Playing -- Chord: \(key), Play Tune: \(value)"
    }
}

import std.collection.ArrayList

class AvgPartition {

    /*
    This is a class that partitions the given list into different blocks by specifying the number of partitions, with each block having a uniformly distributed length.
    */

    let lst: ArrayList<Int64>
    let limit: Int64

    public init(lst: ArrayList<Int64>, limit: Int64) {
        /*
        Initialize the class with the given list and the number of partitions, and check if the number of partitions is greater than 0.
        */
        this.lst = lst
        this.limit = limit
    }

    public func setNum(): (Int64, Int64) {
        /*
        Calculate the size of each block and the remainder of the division.
        :return: the size of each block and the remainder of the division, tuple.
        >>> a = AvgPartition(ArrayList<Int64>([1, 2, 3, 4]), 2)
        >>> a.setNum()
        (2, 0)

        */
        let size = this.lst.size() / this.limit
        let remainder = this.lst.size() % this.limit
        return (size, remainder)
    }

    public func get(index: Int64): ArrayList<Int64> {
        /*
        calculate the size of each block and the remainder of the division, and calculate the corresponding start and end positions based on the index of the partition.
        :param index: the index of the partition, Int64.
        :return: the corresponding block, ArrayList<Int64>.
        >>> a = AvgPartition(ArrayList<Int64>([1, 2, 3, 4]), 2)
        >>> a.get(0)
        [1, 2]

        */
        let (size, remainder) = this.setNum()
        let start = index * size + min(index, remainder)
        var end = start + size
        if index + 1 <= remainder {
            end = end + 1
        }
        let result = ArrayList<Int64>()
        var i = start
        while i < end {
            result.add(this.lst.get(i))
            i = i + 1
        }
        return result
    }
}

import std.collection.ArrayList

class BalancedBrackets {

    /*
    This is a class that checks for bracket matching
    */

    let stack: ArrayList<String>
    let left_brackets: ArrayList<String>
    let right_brackets: ArrayList<String>
    var expr: String

    public init(expr: String) {
        /*
        Initializes the class with an expression.
        :param expr: The expression to check for balanced brackets,String.
        */
        this.stack = ArrayList<String>()
        this.left_brackets = ArrayList<String>(["(", "{", "["])
        this.right_brackets = ArrayList<String>([")", "}", "]"])
        this.expr = expr
    }

    public func clear_expr(): Unit {
        /*
        Clears the expression of all characters that are not brackets.
        >>> b = BalancedBrackets("a(b)c")
        >>> b.clear_expr()
        >>> b.expr
        '()'

        */
        var cleaned = ""
        for c in this.expr {
            if this.left_brackets.contains(c) || this.right_brackets.contains(c) {
                cleaned = cleaned + c
            }
        }
        this.expr = cleaned
    }

    public func check_balanced_brackets(): Bool {
        /*
        Checks if the expression has balanced brackets.
        :return: true if the expression has balanced brackets, false otherwise.
        >>> b = BalancedBrackets("a(b)c")
        >>> b.check_balanced_brackets()
        true

        */
        this.clear_expr()
        for Brkt in this.expr {
            if this.left_brackets.contains(Brkt) {
                this.stack.add(Brkt)
            } else {
                if this.stack.isEmpty() {
                    return false
                }
                let Current_Brkt = this.stack.removeLast()
                if Current_Brkt == "(" {
                    if Brkt != ")" {
                        return false
                    }
                }
                if Current_Brkt == "{" {
                    if Brkt != "}" {
                        return false
                    }
                }
                if Current_Brkt == "[" {
                    if Brkt != "]" {
                        return false
                    }
                }
            }
        }
        return this.stack.isEmpty()
    }
}

class BankAccount {

    /*
    This is a class as a bank account system, which supports deposit money, withdraw money, view balance, and transfer money.
    */

    var balance: Int64

    public init(balance!: Int64 = 0) {
        /*
        Initializes a bank account object with an attribute balance, default value is 0.
        */
        this.balance = balance
    }

    public func deposit(amount: Int64): Int64 {
        /*
        Deposits a certain amount into the account, increasing the account balance, return the current account balance.
        If amount is negative, throw Exception("Invalid amount").
        :param amount: Int64
        */
        if amount < 0 {
            throw Exception("Invalid amount")
        }
        this.balance += amount
        return this.balance
    }

    public func withdraw(amount: Int64): Int64 {
        /*
        Withdraws a certain amount from the account, decreasing the account balance, return the current account balance.
        If amount is negative, throw Exception("Invalid amount").
        If the withdrawal amount is greater than the account balance, throw Exception("Insufficient balance.").
        :param amount: Int64
        */
        if amount < 0 {
            throw Exception("Invalid amount")
        }
        if amount > this.balance {
            throw Exception("Insufficient balance.")
        }
        this.balance -= amount
        return this.balance
    }

    public func view_balance(): Int64 {
        /*
        Return the account balance.
        */
        return this.balance
    }

    public func transfer(other_account: BankAccount, amount: Int64): Unit {
        /*
        Transfers a certain amount from the current account to another account.
        :param other_account: BankAccount
        :param amount: Int64
        >>> account1 = BankAccount()
        >>> account2 = BankAccount()
        >>> account1.deposit(1000)
        >>> account1.transfer(account2, 300)
        account1.balance = 700 account2.balance = 300
        */
        this.withdraw(amount)
        other_account.deposit(amount)
    }
}

import std.convert.Parsable

class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    public static func add(num1: String, num2: String): String {
        let max_length = max(num1.length, num2.length)
        var padded_num1 = num1
        var padded_num2 = num2

        while padded_num1.length < max_length {
            padded_num1 = "0" + padded_num1
        }

        while padded_num2.length < max_length {
            padded_num2 = "0" + padded_num2
        }

        var carry = 0
        var result: List<String> = []

        for i in (0..max_length).reversed() {
            let digit_sum = Int.parse(padded_num1[i]) + Int.parse(padded_num2[i]) + carry
            carry = digit_sum / 10
            let digit = digit_sum % 10
            result.insert(0, String(digit))
        }

        if carry > 0 {
            result.insert(0, String(carry))
        }

        return result.join("")
    }

    public static func subtract(num1: String, num2: String): String {
        var negative = false
        var n1 = num1
        var n2 = num2

        if n1.length < n2.length {
            let temp = n1
            n1 = n2
            n2 = temp
            negative = true
        } else if n1.length > n2.length {
            negative = false
        } else {
            if n1 < n2 {
                let temp = n1
                n1 = n2
                n2 = temp
                negative = true
            } else {
                negative = false
            }
        }

        let max_length = max(n1.length, n2.length)
        var padded_n1 = n1
        var padded_n2 = n2

        while padded_n1.length < max_length {
            padded_n1 = "0" + padded_n1
        }

        while padded_n2.length < max_length {
            padded_n2 = "0" + padded_n2
        }

        var borrow = 0
        var result: List<String> = []

        for i in (0..max_length).reversed() {
            var digit_diff = Int.parse(padded_n1[i]) - Int.parse(padded_n2[i]) - borrow

            if digit_diff < 0 {
                digit_diff += 10
                borrow = 1
            } else {
                borrow = 0
            }

            result.insert(0, String(digit_diff))
        }

        while result.length > 1 && result[0] == "0" {
            result.removeAt(0)
        }

        if negative {
            result.insert(0, "-")
        }

        return result.join("")
    }

    public static func multiply(num1: String, num2: String): String {
        let len1 = num1.length
        let len2 = num2.length
        var result: List<Int> = []

        for _ in 0..(len1 + len2) {
            result.add(0)
        }

        for i in (0..len1).reversed() {
            for j in (0..len2).reversed() {
                let mul = Int.parse(num1[i]) * Int.parse(num2[j])
                let p1 = i + j
                let p2 = i + j + 1
                let total = mul + result[p2]

                result[p1] += total / 10
                result[p2] = total % 10
            }
        }

        var start = 0
        while start < result.length - 1 && result[start] == 0 {
            start += 1
        }

        var final_result: List<String> = []
        for i in start..result.length {
            final_result.add(String(result[i]))
        }

        return final_result.join("")
    }
}

import std.collection.HashMap
import std.convert.RadixConvertible

class BinaryDataProcessor {

    var binary_string: String

    public init(binary_string: String) {
        this.binary_string = binary_string
        this.clean_non_binary_chars()
    }

    public func clean_non_binary_chars(): Unit {
        var cleaned = ""
        for (char in this.binary_string) {
            if (char == '0' || char == '1') {
                cleaned = cleaned + char
            }
        }
        this.binary_string = cleaned
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        let zeroes_count = this.binary_string.count('0')
        let ones_count = this.binary_string.count('1')
        let total_length = this.binary_string.length

        let zeroes_percentage = Float64(zeroes_count) / Float64(total_length)
        let ones_percentage = Float64(ones_count) / Float64(total_length)

        let result = HashMap<String, Float64>()
        result.put("Zeroes", zeroes_percentage)
        result.put("Ones", ones_percentage)
        result.put("Bit length", Float64(total_length))

        return result
    }

    public func convert_to_ascii(): String {
        var result = ""
        for (i in 0..<this.binary_string.length step 8) {
            let end = if (i + 8 < this.binary_string.length) i + 8 else this.binary_string.length
            let byte_str = this.binary_string.substring(i, end)
            let decimal = Int32.parse_with_radix(byte_str, 2)
            result = result + Char(decimal).to_string()
        }
        return result
    }

    public func convert_to_utf8(): String {
        var result = ""
        for (i in 0..<this.binary_string.length step 8) {
            let end = if (i + 8 < this.binary_string.length) i + 8 else this.binary_string.length
            let byte_str = this.binary_string.substring(i, end)
            let decimal = Int32.parse_with_radix(byte_str, 2)
            result = result + Char(decimal).to_string()
        }
        return result
    }
}

class BitStatusUtil {

    /*
    This is a utility class that provides methods for manipulating and checking status using bitwise operations.
    */

    public static func add(states: Int64, stat: Int64): Int64 {
        BitStatusUtil.check([states, stat])
        return states | stat
    }

    public static func has(states: Int64, stat: Int64): Bool {
        BitStatusUtil.check([states, stat])
        return (states & stat) == stat
    }

    public static func remove(states: Int64, stat: Int64): Int64 {
        BitStatusUtil.check([states, stat])
        if (BitStatusUtil.has(states, stat)) {
            return states ^ stat
        }
        return states
    }

    public static func check(args: Array<Int64>): Unit {
        for (arg in args) {
            if (arg < 0) {
                throw Exception("${arg} must be greater than or equal to 0")
            }
            if (arg % 2 != 0) {
                throw Exception("${arg} not even")
            }
        }
    }
}

import std.random.Random
import std.collection.ArrayList
import std.convert.Parsable

class BlackjackGame {

    /*
    This is a class representing a game of blackjack, which includes creating a deck, calculating the value of a hand, and determine the winner based on the hand values of the player and dealer.
    */

    let deck: ArrayList<String>
    let player_hand: ArrayList<String>
    let dealer_hand: ArrayList<String>

    public init() {
        /*
        Initialize the Blackjack Game with the attribute deck, player_hand and dealer_hand.
        While initializing deck attribute, call the create_deck method to generate.
        The deck stores 52 rondom order poker with the Jokers removed, format is ['AS', '2S', ...].
        player_hand is a ArrayList<String> which stores player's hand cards.
        dealer_hand is is a ArrayList<String> which stores dealer's hand cards.
        */
        this.deck = BlackjackGame.create_deck()
        this.player_hand = ArrayList<String>()
        this.dealer_hand = ArrayList<String>()
    }

    public static func shuffle_arraylist(arr: ArrayList<String>): ArrayList<String> {
        /*
        Shuffles the input ArrayList of strings using the Fisher-Yates (Knuth) shuffle algorithm.
        This algorithm produces a uniformly random permutation by swapping each element 
        with a randomly selected element that comes before it (including itself) in the list,
        ensuring each element has an equal probability of being in any position.

        :param arr: The ArrayList of strings to be shuffled
        :return: The shuffled ArrayList of strings (same object as input, shuffled in-place)
        */
        let rnd = Random()
        for (i in (arr.size - 1)..0:-1) {
            let j = rnd.nextInt64(i + 1)
            //  swap arr[i] and arr[j]
            let temp = arr[i]
            arr[i] = arr[j]
            arr[j] = temp
        }
        return arr
    }

    public static func create_deck(): ArrayList<String> {
        /*
        Create a deck of 52 cards, which stores 52 rondom order poker with the Jokers removed.
        :return: a list of 52 rondom order poker with the Jokers removed, format is ['AS', '2S', ...].()
        >>> BlackjackGame.create_deck()
        ['QD', '9D', 'JC', 'QH', '2S', 'JH', '7D', '6H', '9S', '5C', '7H', 'QS', '5H',
        '6C', '7C', '3D', '10C', 'AD', '4C', '5D', 'AH', '2D', 'QC', 'KH', '9C', '9H',
        '4H', 'JS', '6S', '8H', '8C', '4S', '3H', '10H', '7S', '6D', '3C', 'KC', '3S',
        '2H', '10D', 'KS', '4D', 'AC', '10S', '2C', 'KD', '5S', 'JD', '8S', 'AS', '8D']
        */
        let suits = ArrayList<String>()
        suits.add("S")
        suits.add("C")
        suits.add("D")
        suits.add("H")

        let ranks = ArrayList<String>()
        ranks.add("A")
        ranks.add("2")
        ranks.add("3")
        ranks.add("4")
        ranks.add("5")
        ranks.add("6")
        ranks.add("7")
        ranks.add("8")
        ranks.add("9")
        ranks.add("10")
        ranks.add("J")
        ranks.add("Q")
        ranks.add("K")

        let deck = ArrayList<String>()
        for (suit in suits) {
            for (rank in ranks) {
                deck.add(rank + suit)
            }
        }
        return BlackjackGame.shuffle_arraylist(deck)
    }

    public func calculate_hand_value(hand: ArrayList<String>): Int64 {
        /*
        Calculate the value of the poker cards stored in hand list according to the rules of the Blackjack Game.
        If the card is a digit, its value is added to the total hand value.
        Value of J, Q, or K is 10, while Aces are worth 11.
        If the total hand value exceeds 21 and there are Aces present, one Ace is treated as having a value of 1 instead of 11,
        until the hand value is less than or equal to 21, or all Aces have been counted as value of 1.
        :param hand: ArrayList<String>
        :return: the value of the poker cards stored in hand list, a number.
        >>> black_jack_game = BlackjackGame()
        >>> black_jack_game.calculate_hand_value(ArrayList<String>(['QD', '9D', 'JC', 'QH', 'AS']))
        40
        */
        var value: Int64 = 0
        var num_aces: Int64 = 0
        for (card in hand) {
            let rank = card.substring(0, card.length - 1)
            if (rank.isDigit) {
                value += rank.parse<Int64>()
            } else if (rank == "J" || rank == "Q" || rank == "K") {
                value += 10
            } else if (rank == "A") {
                value += 11
                num_aces += 1
            }
        }
        while (value > 21 && num_aces > 0) {
            value -= 10
            num_aces -= 1
        }
        return value
    }

    public func check_winner(player_hand: ArrayList<String>, dealer_hand: ArrayList<String>): String {
        /*
        Determines the winner of a game by comparing the hand values of the player and dealer.
        rule:
        If both players have hand values that are equal to or less than 21, the winner is the one whose hand value is closer to 21.
        Otherwise, the winner is the one with the lower hand value.
        :param player_hand: ArrayList<String>
        :param dealer_hand: ArrayList<String>
        :return: the result of the game, only two certain String: 'Dealer wins' or 'Player wins'
        >>> black_jack_game = BlackjackGame()
        >>> black_jack_game.check_winner(ArrayList<String>(['QD', '9D', 'JC', 'QH', 'AS']), ArrayList<String>(['QD', '9D', 'JC', 'QH', '2S']))
        'Player wins'
        */
        let player_value = this.calculate_hand_value(player_hand)
        let dealer_value = this.calculate_hand_value(dealer_hand)
        if (player_value > 21 && dealer_value > 21) {
            if (player_value <= dealer_value) {
                return "Player wins"
            } else {
                return "Dealer wins"
            }
        } else if (player_value > 21) {
            return "Dealer wins"
        } else if (dealer_value > 21) {
            return "Player wins"
        } else {
            if (player_value <= dealer_value) {
                return "Dealer wins"
            } else {
                return "Player wins"
            }
        }
    }
}

import std.collection.HashMap

class BookManagement {

    /*
    This is a class as managing books system, which supports to add and remove books from the inventory dict, view the inventory, and check the quantity of a specific book.
    */

    let inventory: HashMap<String, Int64>

    public init() {
        /*
        Initialize the inventory of Book Manager.
        */
        this.inventory = HashMap<String, Int64>()
    }

    public func add_book(title: String, quantity!: Int64=1): Unit {
        /*
        Add one or several books to inventory which is sorted by book title.
        :param title: String, the book title
        :param quantity: Int64, default value is 1.
        */
        if this.inventory.containsKey(title) {
            let current = this.inventory.get(title)!
            this.inventory.put(title, current + quantity)
        } else {
            this.inventory.put(title, quantity)
        }
    }

    public func remove_book(title: String, quantity: Int64): Unit {
        /*
        Remove one or several books from inventory which is sorted by book title.
        throw Exception("Invalid operation") while get invalid input.
        :param title: String, the book title
        :param quantity: Int64
        */
        if !this.inventory.containsKey(title) || this.inventory.get(title)! < quantity {
            throw Exception("Invalid operation")
        }
        let current = this.inventory.get(title)!
        if current == quantity {
            this.inventory.remove(title)
        } else {
            this.inventory.put(title, current - quantity)
        }
    }

    public func view_inventory(): HashMap<String, Int64> {
        /*
        Get the inventory of the Book Management.
        :return this.inventory: HashMap<String, Int64>
        >>> bookManagement = BookManagement()
        >>> bookManagement.add_book("book1", quantity: 1)
        >>> bookManagement.add_book("book2", quantity: 1)
        >>> bookManagement.view_inventory()
        {'book1': 1, 'book2': 1}
        */
        return this.inventory
    }

    public func view_book_quantity(title: String): Int64 {
        /*
        Get the quantity of a book.
        :param title: String, the title of the book.
        :return quantity: the quantity of this book title. return 0 when the title does not exist in this.inventory
        >>> bookManagement = BookManagement()
        >>> bookManagement.add_book("book1", quantity: 1)
        >>> bookManagement.view_book_quantity("book3")
        0
        */
        if this.inventory.containsKey(title) {
            return this.inventory.get(title)!
        } else {
            return 0
        }
    }
}

import std.collection.ArrayList

class BoyerMooreSearch {
    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        this.text = text
        this.pattern = pattern
        this.textLen = text.size
        this.patLen = pattern.size
    }

    public func match_in_pattern(char: String): Int64 {
        var i: Int64 = this.patLen - 1
        while i >= 0 {
            if this.pattern[i] == char {
                return i
            }
            i = i - 1
        }
        return -1
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        var i: Int64 = this.patLen - 1
        while i >= 0 {
            if this.pattern[i] != this.text[currentPos + i] {
                return currentPos + i
            }
            i = i - 1
        }
        return -1
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        let positions = ArrayList<Int64>()
        var i: Int64 = 0
        while i <= this.textLen - this.patLen {
            let mismatch_index = this.mismatch_in_text(i)
            if mismatch_index == -1 {
                positions.add(i)
                i = i + 1
            } else {
                let match_index = this.match_in_pattern(this.text[mismatch_index])
                if match_index == -1 {
                    i = mismatch_index + 1
                } else {
                    i = mismatch_index - match_index
                }
            }
        }
        return positions
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.convert.Parsable

class Calculator {

    /*
    This is a class for a calculator, capable of performing basic arithmetic calculations on numerical expressions using the operators +, -, *, /, and ^ (exponentiation).
    */

    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        /*
        Initialize the operations performed by the five operators'+','-','*','/','^'
        */
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        let operand_stack = ArrayList<Float64>()
        let operator_stack = ArrayList<String>()
        var num_buffer = ""

        for (char in expression) {
            if (char.isDigit() || char == '.') {
                num_buffer += char
            } else {
                if (!num_buffer.isEmpty()) {
                    operand_stack.add(num_buffer.toFloat64())
                    num_buffer = ""
                }

                if ("+-*/^".contains(char)) {
                    while (!operator_stack.isEmpty() && 
                           operator_stack.last() != "(" && 
                           this.precedence(operator_stack.last()) >= this.precedence(char)) {
                        let result = this.apply_operator(operand_stack, operator_stack)
                        operand_stack = result.first
                        operator_stack = result.second
                    }
                    operator_stack.add(char)
                } else if (char == "(") {
                    operator_stack.add(char)
                } else if (char == ")") {
                    while (!operator_stack.isEmpty() && operator_stack.last() != "(") {
                        let result = this.apply_operator(operand_stack, operator_stack)
                        operand_stack = result.first
                        operator_stack = result.second
                    }
                    if (!operator_stack.isEmpty()) {
                        operator_stack.removeLast()
                    }
                }
            }
        }

        if (!num_buffer.isEmpty()) {
            operand_stack.add(num_buffer.toFloat64())
        }

        while (!operator_stack.isEmpty()) {
            let result = this.apply_operator(operand_stack, operator_stack)
            operand_stack = result.first
            operator_stack = result.second
        }

        if (operand_stack.isEmpty()) {
            return None
        } else {
            return Some(operand_stack.last())
        }
    }

    public func precedence(op: String): Int64 {
        let precedences = HashMap<String, Int64>()
        precedences.add("+", 1)
        precedences.add("-", 1)
        precedences.add("*", 2)
        precedences.add("/", 2)
        precedences.add("^", 3)
        return precedences.get(op).getOrElse(0)
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        let operator = operator_stack.removeLast()
        let operand2 = operand_stack.removeLast()
        let operand1 = operand_stack.removeLast()
        let result = this.operators.get(operator).get()(operand1, operand2)
        operand_stack.add(result)
        return (operand_stack, operator_stack)
    }
}

import std.time.DateTime
import std.collection.ArrayList

class Event <: Equatable<Event> {

    let date: DateTime
    let start_time: DateTime
    let end_time: DateTime
    let description: String

    public init(date: DateTime, start_time: DateTime, end_time: DateTime, description: String) {
        this.date = date
        this.start_time = start_time
        this.end_time = end_time
        this.description = description
    }

    public override operator func != (that: Event): Bool {
        return this.date != that.date || this.start_time != that.start_time || this.end_time != that.end_time || this.description != that.description
    }

    public override operator func == (that: Event): Bool {
        return this.date == that.date && this.start_time == that.start_time && this.end_time == that.end_time && this.description == that.description
    }
}

class CalendarUtil {

    let events: ArrayList<Event>

    public init() {
        this.events = ArrayList<Event>()
    }

    public func add_event(event: Event): Unit {
        this.events.add(event)
    }

    public func remove_event(event: Event): Unit {
        this.events.remove(event)
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let result = ArrayList<Event>()
        for event in this.events {
            if event.date.date() == date.date() {
                result.add(event)
            }
        }
        return result
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        for event in this.events {
            if start_time < event.end_time && end_time > event.start_time {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let available_slots = ArrayList<(DateTime, DateTime)>()
        let start_of_day = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 0, minute: 0)
        let end_of_day = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 23, minute: 59)

        var current_time = start_of_day
        while current_time < end_of_day {
            let slot_end_time = current_time.addMinutes(60)
            if this.is_available(current_time, slot_end_time) {
                available_slots.add((current_time, slot_end_time))
            }
            current_time = current_time.addMinutes(60)
        }

        return available_slots
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let now = DateTime.now()
        let upcoming_events = ArrayList<Event>()
        for event in this.events {
            if event.start_time >= now {
                upcoming_events.add(event)
                if upcoming_events.size() == num_events {
                    break
                }
            }
        }
        return upcoming_events
    }
}

import std.collection.HashMap

class CamelCaseMap {

    /*
    This is a custom class that allows keys to be in camel case style by converting them from underscore style, which provides dictionary-like functionality.
    */

    let _data: HashMap<String, Any>

    public init() {
        /*
        Initialize data to an empty dictionary
        */
        _data = HashMap<String, Any>()
    }

    public func __getitem__(key: String): Any {
        /*
        Return the value corresponding to the key
        :param key:String
        :return:Any,the value corresponding to the key
        >>> camelize_map = CamelCaseMap()
        >>> camelize_map.__setitem__('first_name', 'John')
        >>> camelize_map.__getitem__('first_name')
        'John'
        */
        let converted_key = _convert_key(key) as String
        return _data.get(converted_key)
    }

    public func __setitem__(key: String, value: Any): Unit {
        /*
        Set the value corresponding to the key to the specified value
        :param key:String
        :param value:Any, the specified value
        :return:Unit
        >>> camelize_map = CamelCaseMap()
        >>> camelize_map.__setitem__('first_name', 'John')
        >>> camelize_map.__setitem__('first_name', 'new name')
        >>> camelize_map.__getitem__('first_name')
        'new name'
        */
        let converted_key = _convert_key(key) as String
        _data.put(converted_key, value)
    }

    public func __delitem__(key: String): Unit {
        /*
        Delete the value corresponding to the key
        :param key:String
        :return:Unit
        >>> camelize_map = CamelCaseMap()
        >>> camelize_map.__setitem__('first_name', 'John')
        >>> camelize_map.__delitem__('first_name')
        >>> flag = camelize_map._data.contains(camelize_map.to_camel_case('first_name'))
        flag = false
        */
        let converted_key = _convert_key(key) as String
        _data.remove(converted_key)
    }

    public func __len__(): Int64 {
        /*
        Returns the length of the own data
        :return:Int64, length of data
        >>> camelize_map = CamelCaseMap()
        >>> camelize_map.__setitem__('first_name', 'John')
        >>> camelize_map.__setitem__('last_name', 'Doe')
        >>> camelize_map.__setitem__('age', 30)
        >>> camelize_map.__len__()
        3
        */
        return _data.size()
    }

    public func _convert_key(key: Any): Any {
        /*
        convert key string into camel case
        If key is not String type, return key directly
        :param key:Any
        :return:Any, converted key string
        >>> camelize_map = CamelCaseMap()
        >>> (camelize_map._convert_key('first_name') as String) ?? ""
        'firstName'
        >>> (camelize_map._convert_key(123) as Int64) ?? 0
        123
        */
        if key is String {
            return _to_camel_case(key as String)
        } else {
            return key
        }
    }

    public static func _to_camel_case(key: String): String {
        /*
        convert key string into camel case
        :param key:String
        :return:String, converted key string
        >>> CamelCaseMap._to_camel_case('first_name')
        'firstName'
        */
        let parts = key.split("_")
        if parts.size() == 0 {
            return ""
        }
        let first_part = parts[0]
        let rest_parts = parts.slice(1)
        let capitalized_rest = rest_parts.map(func (s: String): String = s.capitalize())
        return first_part + capitalized_rest.join("")
    }
}

import std.collection.ArrayList

class ChandrasekharSieve {

    /*
    This is a class that uses the Chandrasekhar's Sieve method to find all prime numbers within the range
    */

    let n: Int64
    var primes: ArrayList<Int64> = ArrayList<Int64>()

    public init(n: Int64) {
        /*
        Initialize the ChandrasekharSieve class with the given limit.
        :param n: Int64, the upper limit for generating prime numbers
        */
        this.n = n
        this.primes = generate_primes()
    }

    public func generate_primes(): ArrayList<Int64> {
        /*
        Generate prime numbers up to the specified limit using the Chandrasekhar sieve algorithm.
        :return: ArrayList<Int64>, a list of prime numbers
        >>> cs = ChandrasekharSieve(20)
        >>> cs.generate_primes()
        [2, 3, 5, 7, 11, 13, 17, 19]

        */
        if this.n < 2 {
            return ArrayList<Int64>()
        }

        // Create a boolean array "sieve[0..n]" and initialize all entries as true.
        let sieve: ArrayList<Bool> = ArrayList<Bool>()
        for _ in 0..(this.n + 1) {
            sieve.add(true)
        }
        sieve.set(0, false)
        sieve.set(1, false)

        let p: Int64 = 2
        while p * p <= this.n {
            if sieve.get(p) {
                // Mark all multiples of p as not prime
                var i: Int64 = p * p
                while i <= this.n {
                    sieve.set(i, false)
                    i += p
                }
            }
            p += 1
        }

        // Collect all prime numbers
        let primes: ArrayList<Int64> = ArrayList<Int64>()
        var j: Int64 = 2
        while j <= this.n {
            if sieve.get(j) {
                primes.add(j)
            }
            j += 1
        }

        return primes
    }

    public func get_primes(): ArrayList<Int64> {
        /*
        Get the list of generated prime numbers.
        :return: ArrayList<Int64>, a list of prime numbers
        >>> cs = ChandrasekharSieve(20)
        >>> cs.get_primes()
        [2, 3, 5, 7, 11, 13, 17, 19]

        */
        return this.primes
    }
}

