class HRManagementSystem {

    var employees: HashMap<Int64, Employee>

    public init() {
        this.employees = HashMap<Int64, Employee>()
    }

    public func add_employee(employee_id: Int64, name: String, position: String, department: String, salary: Int64): Bool {
        if this.employees.contains(employee_id) {
            return false
        } else {
            this.employees.add(employee_id, Employee(name, position, department, salary))
            return true
        }
    }

    public func remove_employee(employee_id: Int64): Bool {
        if this.employees.contains(employee_id) {
            this.employees.remove(employee_id)
            return true
        } else {
            return false
        }
    }

    public func update_employee(employee_id: Int64, employee_info: HashMap<String, Any>): Bool {
        if !this.employees.contains(employee_id) {
            return false
        }

        var employee = this.employees[employee_id]
        for entry in employee_info.entrySet() {
            let key = entry.key
            let value = entry.value
            switch key {
                case "name" => if let newName = value as? String { employee.name = newName } else { return false }
                case "position" => if let newPosition = value as? String { employee.position = newPosition } else { return false }
                case "department" => if let newDepartment = value as? String { employee.department = newDepartment } else { return false }
                case "salary" => if let newSalary = value as? Int64 { employee.salary = newSalary } else { return false }
                default => return false
            }
        }
        this.employees.set(employee_id, employee)
        return true
    }

    public func get_employee(employee_id: Int64): Option<Employee> {
        if this.employees.contains(employee_id) {
            return Some(this.employees[employee_id])
        } else {
            return None()
        }
    }

    public func list_employees(): ArrayList<Employee> {
        let employee_list = ArrayList<Employee>()
        for entry in this.employees.entrySet() {
            employee_list.add(entry.value)
        }
        return employee_list
    }
}

import std.collection.ArrayList

class Interpolation {

    /*
    This is a class that implements the Linear interpolation operation of one-dimensional and two-dimensional data
    */

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let y_interp = ArrayList<Float64>()
        for xi in x_interp {
            for i in 0..<x.size() - 1 {
                if x[i] <= xi && xi <= x[i + 1] {
                    let yi = y[i] + (y[i + 1] - y[i]) * (xi - x[i]) / (x[i + 1] - x[i])
                    y_interp.add(yi)
                    break
                }
            }
        }
        return y_interp
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let z_interp = ArrayList<Float64>()
        for idx in 0..<x_interp.size() {
            let xi = x_interp[idx]
            let yi = y_interp[idx]
            for i in 0..<x.size() - 1 {
                if x[i] <= xi && xi <= x[i + 1] {
                    for j in 0..<y.size() - 1 {
                        if y[j] <= yi && yi <= y[j + 1] {
                            let z00 = z[i][j]
                            let z01 = z[i][j + 1]
                            let z10 = z[i + 1][j]
                            let z11 = z[i + 1][j + 1]
                            let dx = x[i + 1] - x[i]
                            let dy = y[j + 1] - y[j]
                            let zi = (z00 * (x[i + 1] - xi) * (y[j + 1] - yi) +
                                      z10 * (xi - x[i]) * (y[j + 1] - yi) +
                                      z01 * (x[i + 1] - xi) * (yi - y[j]) +
                                      z11 * (xi - x[i]) * (yi - y[j])) / (dx * dy)
                            z_interp.add(zi)
                            break
                        }
                    }
                    break
                }
            }
        }
        return z_interp
    }
}

