        for entry in users.entries() {
            if !entry.value {
                not_signed_in_users.add(entry.key)
            }
        }
        return not_signed_in_users
    }
}

import std.collection.ArrayList
import std.regex.Regex
import std.unicode.UnicodeStringExtension

class SplitSentence {

    /*
    The class allows to split sentences, count words in a sentence, and process a text file to find the maximum word count.
    */

    public func split_sentences(sentences_string: String): ArrayList<String> {
        /*
        Split a string into a list of sentences. Sentences end with . or ? and with a space after that. Please note that Mr. also end with . but are not sentences.
        :param sentences_string: String, string to split
        :return: ArrayList<String>, split sentence list
        >>> ss = SplitSentence()
        >>> ss.split_sentences("aaa aaaa. bb bbbb bbb? cccc cccc. dd ddd?")
        ['aaa aaaa.', 'bb bbbb bbb?', 'cccc cccc.', 'dd ddd?']
        */
        let pattern = "(?<!\\w\\.\\w.)(?<![A-Z][a-z]\\.)(?<=\\.|\\?)\\s"
        let regex = Regex(pattern)
        let result = regex.split(sentences_string)
        let sentences = ArrayList<String>()
        for item in result {
            sentences.add(item)
        }
        return sentences
    }

    public func count_words(sentence: String): Int64 {
        /*
        Count the number of words in a sentence. Note that words are separated by spaces and that punctuation marks and numbers are not counted as words.
        :param sentence:String, sentence to be counted, where words are separated by spaces
        :return:Int64, number of words in the sentence
        >>> ss.count_words("abc def")
        2
        */
        var cleaned = ""
        for c in sentence {
            if (c.isLetter() || c == ' ') {
                cleaned = cleaned + c.toString()
            }
        }
        let words = cleaned.trim().split(' ')
        var count: Int64 = 0
        for word in words {
            if (!word.isEmpty()) {
                count = count + 1
            }
        }
        return count
    }

    public func process_text_file(sentences_string: String): Int64 {
        /*
        Given a text, return the number of words in the longest sentence
        :param sentences_string: String, undivided long sentence
        :return:Int64, the number of words in the longest sentence
        >>> ss.process_text_file("aaa aaaa. bb bbbb bbb? cccc ccccccc cc ccc. dd ddd?")
        4
        */
        let sentences = self.split_sentences(sentences_string)
        var max_count: Int64 = 0
        for sentence in sentences {
            let count = self.count_words(sentence)
            if (count > max_count) {
                max_count = count
            }
        }
        return max_count
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class SQLGenerator {

    /*
    This class generates SQL statements for common operations on a table, such as SELECT, INSERT, UPDATE, and DELETE.
    */

    let table_name: String

    public init(table_name: String) {
        /*
        Initialize the table name.
        :param table_name: String
        */
        this.table_name = table_name
    }

    public func select(fields!: Option<ArrayList<String>> = None, condition!: Option<String> = None): String {
        /*
        Generates a SELECT SQL statement based on the specified fields and conditions.
        :param fields: Option<ArrayList<String>>, optional. Default is None. The list of fields to be queried.
        :param condition: Option<String>, optional. Default is None. The condition expression for the query.
        :return: String. The generated SQL statement.
        >>> sql = SQLGenerator("table1")
        >>> sql.select(fields: ArrayList<String>(["field1", "field2"]), condition: "filed3 = value1")
        'SELECT field1, field2 FROM table1 WHERE filed3 = value1;'
        */
        let field_str: String
        if fields!.is_some() {
            let field_list = fields!.unwrap()
            field_str = field_list.join(", ")
        } else {
            field_str = "*"
        }

        var sql = "SELECT \(field_str) FROM \(this.table_name)"
        if condition!.is_some() {
            sql = "\(sql) WHERE \(condition!.unwrap())"
        }
        return "\(sql);"
    }

    public func insert(data: HashMap<String, String>): String {
        /*
        Generates an INSERT SQL statement based on the given data.
        :param data: HashMap<String, String>. The data to be inserted, in dictionary form where keys are field names and values are field values.
        :return: String. The generated SQL statement.
        >>> sql.insert(HashMap<String, String>([('key1', 'value1'), ('key2', 'value2')]))
        "INSERT INTO table1 (key1, key2) VALUES ('value1', 'value2');"
        */
        let keys = data.keys()
        let values = data.values()
        let fields = keys.join(", ")
        let value_list = values.map { |v| "'\(v)'" }
        let value_str = value_list.join(", ")
        return "INSERT INTO \(this.table_name) (\(fields)) VALUES (\(value_str));"
    }

    public func update(data: HashMap<String, String>, condition: String): String {
        /*
        Generates an UPDATE SQL statement based on the given data and condition.
        :param data: HashMap<String, String>. The data to be updated, in dictionary form where keys are field names and values are new field values.
        :param condition: String. The condition expression for the update.
        :return: String. The generated SQL statement.
        >>> sql.update(HashMap<String, String>([('field1', 'new_value1'), ('field2', 'new_value2')]), "field3 = value1")
        "UPDATE table1 SET field1 = 'new_value1', field2 = 'new_value2' WHERE field3 = value1;"
        */
        let set_parts = ArrayList<String>()
        for key in data.keys() {
            let value = data.get(key)!
            set_parts.add("\(key) = '\(value)'")
        }
        let set_clause = set_parts.join(", ")
        return "UPDATE \(this.table_name) SET \(set_clause) WHERE \(condition);"
    }

    public func delete(condition: String): String {
        /*
        Generates a DELETE SQL statement based on the given condition.
        :param condition: String. The condition expression for the delete.
        :return: String. The generated SQL statement.
        >>> sql.delete("field1 = value1")
        'DELETE FROM table1 WHERE field1 = value1;'
        */
        return "DELETE FROM \(this.table_name) WHERE \(condition);"
    }

    public func select_female_under_age(age: Int64): String {
        /*
        Generates a SQL statement to select females under a specified age.
        :param age: Int64. The specified age.
        :return: String. The generated SQL statement.
        >>> sql.select_female_under_age(30)
        "SELECT * FROM table1 WHERE age < 30 AND gender = 'female';"
        */
        let condition = "age < \(age) AND gender = 'female'"
        return this.select(condition: Some(condition))
    }

    public func select_by_age_range(min_age: Int64, max_age: Int64): String {
        /*
        Generates a SQL statement to select records within a specified age range.
        :param min_age: Int64. The minimum age.
        :param max_age: Int64. The maximum age.
        :return: String. The generated SQL statement.
        >>> sql.select_by_age_range(20, 30)
        'SELECT * FROM table1 WHERE age BETWEEN 20 AND 30;'
        */
        let condition = "age BETWEEN \(min_age) AND \(max_age)"
        return this.select(condition: Some(condition))
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class SQLQueryBuilder {

    public static func select(table: String, columns!: ArrayList<String> = ArrayList<String>(['*']), where_condition!: Option<HashMap<String, String>> = None): String {
        var column_str: String
        if columns.size() == 1 && columns.get(0) == "*" {
            column_str = "*"
        } else {
            column_str = columns.join(", ")
        }

        var query = "SELECT " + column_str + " FROM " + table

        if let where_map = where_condition {
            var conditions = ArrayList<String>()
            for entry in where_map.entries() {
                conditions.add(entry.key + "='" + entry.value + "'")
            }
            query = query + " WHERE " + conditions.join(" AND ")
        }

        return query
    }

    public static func insert(table: String, data: HashMap<String, String>): String {
        var keys = ArrayList<String>()
        var values = ArrayList<String>()

        for entry in data.entries() {
            keys.add(entry.key)
            values.add("'" + entry.value + "'")
        }

        var keys_str = keys.join(", ")
        var values_str = values.join(", ")

        return "INSERT INTO " + table + " (" + keys_str + ") VALUES (" + values_str + ")"
    }

    public static func delete(table: String, where_condition!: Option<HashMap<String, String>> = None): String {
        var query = "DELETE FROM " + table

        if let where_map = where_condition {
            var conditions = ArrayList<String>()
            for entry in where_map.entries() {
                conditions.add(entry.key + "='" + entry.value + "'")
            }
            query = query + " WHERE " + conditions.join(" AND ")
        }

        return query
    }

    public static func update(table: String, data: HashMap<String, String>, where_condition!: Option<HashMap<String, String>> = None): String {
        var updates = ArrayList<String>()
        for entry in data.entries() {
            updates.add(entry.key + "='" + entry.value + "'")
        }
        var update_str = updates.join(", ")

        var query = "UPDATE " + table + " SET " + update_str

        if let where_map = where_condition {
            var conditions = ArrayList<String>()
            for entry in where_map.entries() {
                conditions.add(entry.key + "='" + entry.value + "'")
            }
            query = query + " WHERE " + conditions.join(" AND ")
        }

        return query
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        let sorted_data = sort(data)
        let n = sorted_data.size()
        if n % 2 == 1 {
            return Float64(sorted_data[n // 2])
        } else {
            return Float64(sorted_data[n // 2 - 1] + sorted_data[n // 2]) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let counts = HashMap<Int64, Int64>()
        for value in data {
            if counts.containsKey(value) {
                counts.put(value, counts.get(value)! + 1)
            } else {
                counts.put(value, 1)
            }
        }
        let max_count = counts.values().reduce(0, (a, b) -> if a > b { a } else { b })
        let mode_values = ArrayList<Int64>()
        for key in counts.keys() {
            if counts.get(key)! == max_count {
                mode_values.add(key)
            }
        }
        return mode_values
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        let n = x.size()
        if n != y.size() || n == 0 {
            return None
        }
        let mean_x_opt = mean(x)
        let mean_y_opt = mean(y)
        if mean_x_opt.isNone() || mean_y_opt.isNone() {
            return None
        }
        let mean_x = mean_x_opt.unwrap()
        let mean_y = mean_y_opt.unwrap()
        var numerator: Float64 = 0.0
        var sum_xx: Float64 = 0.0
        var sum_yy: Float64 = 0.0
        for i in 0..<n {
            let xi = Float64(x[i])
            let yi = Float64(y[i])
            let dx = xi - mean_x
            let dy = yi - mean_y
            numerator += dx * dy
            sum_xx += dx * dx
            sum_yy += dy * dy
        }
        let denominator = sqrt(sum_xx * sum_yy)
        if abs(denominator) < 1e-10 {
            return None
        }
        return Some(numerator / denominator)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if data.size() == 0 {
            return None
        }
        var sum: Int64 = 0
        for value in data {
            sum += value
        }
        return Some(Float64(sum) / Float64(data.size()))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let n = data.size()
        if n == 0 {
            return ArrayList<ArrayList<Float64>>()
        }
        let m = data[0].size()
        let matrix = ArrayList<ArrayList<Float64>>()
        for i in 0..<m {
            let row = ArrayList<Float64>()
            for j in 0..<m {
                let column1 = ArrayList<Int64>()
                let column2 = ArrayList<Int64>()
                for k in 0..<n {
                    column1.add(data[k][i])
                    column2.add(data[k][j])
                }
                let corr_opt = correlation(column1, column2)
                let corr = if corr_opt.isSome() { corr_opt.unwrap() } else { 0.0 }
                row.add(corr)
            }
            matrix.add(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let n = data.size()
        if n < 2 {
            return None
        }
        let mean_opt = mean(data)
        if mean_opt.isNone() {
            return None
        }
        let mean_val = mean_opt.unwrap()
        var variance: Float64 = 0.0
        for value in data {
            let diff = Float64(value) - mean_val
            variance += diff * diff
        }
        variance /= Float64(n - 1)
        return Some(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let mean_opt = mean(data)
        let std_opt = standard_deviation(data)
        if mean_opt.isNone() || std_opt.isNone() {
            return None
        }
        let mean_val = mean_opt.unwrap()
        let std_val = std_opt.unwrap()
        if abs(std_val) < 1e-10 {
            return None
        }
        let result = ArrayList<Float64>()
        for value in data {
            result.add((Float64(value) - mean_val) / std_val)
        }
        return Some(result)
    }
}

